import pandas as pd


def _values_equal(a, b):
    a_is_na = pd.isna(a)
    b_is_na = pd.isna(b)
    if a_is_na and b_is_na:
        return True
    if a_is_na or b_is_na:
        return False
    return a == b


def _get_input(inputs: dict, *names):
    for n in names:
        if n in inputs:
            return inputs[n]
    # Case-insensitive fallback
    lower_map = {k.lower(): k for k in inputs.keys()}
    for n in names:
        if n.lower() in lower_map:
            return inputs[lower_map[n.lower()]]
    raise KeyError(f"None of {names} found in inputs keys: {list(inputs.keys())}")


def run(inputs: dict) -> dict:
    dim = _get_input(inputs, "DIM_CUSTOMER", "dim_customer").copy()
    stg = _get_input(inputs, "STG_CUSTOMER", "stg_customer").copy()

    # Ensure expected columns exist even if empty frames passed in
    dim_cols = ["customer_id", "name", "segment", "eff_start_date", "eff_end_date", "is_current"]
    for c in dim_cols:
        if c not in dim.columns:
            dim[c] = pd.Series(dtype="object")
    dim = dim[dim_cols]

    stg_cols = ["customer_id", "name", "segment", "update_date"]
    for c in stg_cols:
        if c not in stg.columns:
            stg[c] = pd.Series(dtype="object")
    stg = stg[stg_cols]

    # Step 1: Deduplicate STG_CUSTOMER to latest per customer_id by update_date,
    # ties broken by greater (name, segment) lexicographically.
    if len(stg) > 0:
        stg_sorted = stg.sort_values(
            by=["customer_id", "update_date", "name", "segment"],
            ascending=[True, False, False, False],
            na_position="last",
            kind="mergesort",
        )
        stg_dedup = stg_sorted.drop_duplicates(subset=["customer_id"], keep="first").reset_index(drop=True)
    else:
        stg_dedup = stg.copy()

    # Work on a list of dict rows for the output dimension for easy mutation/append
    out_rows = dim.to_dict("records")

    # Build index of current rows per customer_id (there should be at most one,
    # but handle defensively by taking the first found and only updating it)
    def find_current_index(customer_id):
        for idx, row in enumerate(out_rows):
            if row["customer_id"] == customer_id and row["is_current"] == 1:
                return idx
        return None

    for _, s in stg_dedup.iterrows():
        cust_id = s["customer_id"]
        s_name = s["name"]
        s_segment = s["segment"]
        s_update_date = s["update_date"]

        cur_idx = find_current_index(cust_id)

        if cur_idx is None:
            # INSERT new current row
            out_rows.append({
                "customer_id": cust_id,
                "name": s_name,
                "segment": s_segment,
                "eff_start_date": s_update_date,
                "eff_end_date": None,
                "is_current": 1,
            })
        else:
            c = out_rows[cur_idx]
            name_changed = not _values_equal(c["name"], s_name)
            segment_changed = not _values_equal(c["segment"], s_segment)

            if name_changed or segment_changed:
                # Expire current row
                out_rows[cur_idx] = {
                    **c,
                    "eff_end_date": s_update_date,
                    "is_current": 0,
                }
                # Insert new version
                out_rows.append({
                    "customer_id": cust_id,
                    "name": s_name,
                    "segment": s_segment,
                    "eff_start_date": s_update_date,
                    "eff_end_date": None,
                    "is_current": 1,
                })
            # else: no change, do nothing

    result = pd.DataFrame(out_rows, columns=dim_cols)

    return {"dim_customer_out": result}
